(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">Một chiếc máy tính</span> <span class=\"hl-bright\">đứng về phía bạn.</span>","hero.sub":"Freally OS khởi động trong vài giây, chỉ chạy những gì bạn yêu cầu, và mọi dòng đều được tự viết.","what.title":"Đây là gì","what.p1":"Freally OS là một hệ điều hành máy tính mới, được viết từ lệnh đầu tiên: trình khởi động, nhân, trình điều khiển, màn hình nền và ứng dụng riêng, tất cả bằng Rust, tất cả tự làm.","what.p2":"Ngoài thư viện lõi của Rust, không có dòng mã nào đến từ dự án khác. Nhờ vậy nó có thể hứa điều mà các hệ thống khác chỉ đưa ra như một cài đặt: không có đo lường từ xa để tắt, vì chưa từng được viết.","what.p3":"Vẫn còn sớm. Hôm nay nó khởi động, tự kiểm tra chữ ký của mình, rồi chạy nhân và chương trình đầu tiên. Con đường bên dưới cho thấy từng bước đến 1.0, theo thứ tự.","promises.title":"Ba lời hứa","promises.yours.title":"Của bạn","promises.yours.body":"Không tài khoản, không đám mây và không đo lường từ xa. Cập nhật luôn hỏi trước, và mọi bản cập nhật đều hoàn tác được.","promises.quiet.title":"Yên tĩnh","promises.quiet.body":"Không có gì chạy nếu bạn không khởi động, và mọi tiến trình đều nói trong một câu nó làm gì.","promises.fast.title":"Nhanh","promises.fast.body":"Màn hình nền trong chưa đầy 3 giây, đo ở mọi bản dựng. Thay đổi nào vượt ngân sách đó sẽ không được phát hành.","ladder.title":"Con đường đến 1.0","ladder.intro":"Mỗi phiên bản một dòng, theo thứ tự. Đây cũng chính là chiếc thang mà kế hoạch riêng đi theo: một bên đổi thì cả hai đổi, và một bước kiểm tra bản dựng so sánh chúng.","ladder.rung.v0.1.0":"Nền móng: trình khởi động riêng kiểm tra một ảnh hệ thống đã ký và vẽ màn hình, và mọi kiểm tra chất lượng chạy ở mỗi lần thay đổi.","ladder.rung.v0.2.0":"Freally Core, nhân hệ điều hành: bộ nhớ, ngắt, bộ định thời, bộ lập lịch và thông điệp. Chương trình đầu tiên khởi chạy, và một sự cố để lại báo cáo.","ladder.rung.v0.3.0":"Dịch vụ và trình điều khiển: mọi lõi xử lý, màn hình, bàn phím và chuột, cùng các bản cập nhật tự quay lại nếu thất bại.","ladder.rung.v0.4.0":"Ánh sáng đầu tiên: màn hình nền, một terminal, một shell và Monitor, thứ giải thích mọi tiến trình. Màn hình nền trong chưa đầy 3 giây.","ladder.rung.v0.5.0":"Laptop thật: Freally OS khởi động từ USB trên chiếc laptop đầu tiên của nó.","ladder.rung.v0.6.0":"Công cụ cho nhà phát triển: thay thế một dịch vụ đang chạy tại chỗ và hoàn tác, không cần khởi động lại.","ladder.rung.v0.7.0":"Lưu trữ, tài khoản cục bộ được mã hóa, Cài đặt và Tệp.","ladder.rung.v0.8.0":"Bản dựng cho người thử: bản phát hành đã ký, cập nhật ngoại tuyến và một ảnh riêng cho người thử.","ladder.rung.v0.9.0":"Mạng, và cập nhật trực tuyến luôn hỏi trước.","ladder.rung.v0.10.0":"USB.","ladder.rung.v0.11.0":"Âm thanh.","ladder.rung.v0.11.5":"Cùng nhau: mời bất kỳ ai, trên mọi máy tính hay điện thoại, bằng một liên kết hoặc mã QR, cùng làm việc với bạn trong các ứng dụng bạn chia sẻ.","ladder.rung.v0.12.0":"Ngôn ngữ lập trình riêng của Freally, phiên bản đầu tiên.","ladder.rung.v0.13.0":"Hộp cát cho ứng dụng, và Freally Guard.","ladder.rung.v0.14.0":"Chương trình Linux trong terminal.","ladder.rung.v0.15.0":"Freally OS tự dựng chính mình.","ladder.rung.v0.16.0":"Bàn di chuột, pin, độ sáng và chế độ ngủ.","ladder.rung.v0.17.0":"Wi-Fi.","ladder.rung.v0.18.0":"Hình ảnh, hình nền của riêng bạn, và Ảnh.","ladder.rung.v0.19.0":"Làn sóng ứng dụng đầu tiên.","ladder.rung.v0.20.0":"Trình duyệt: web không có script.","ladder.rung.v0.21.0":"Trình duyệt: JavaScript.","ladder.rung.v0.22.0":"Tiện ích mở rộng trình duyệt và bảo vệ trên web.","ladder.rung.v0.23.0":"Tăng tốc đồ họa.","ladder.rung.v0.24.0":"Tài liệu.","ladder.rung.v0.25.0":"Bảng tính.","ladder.rung.v0.26.0":"Trình chiếu.","ladder.rung.v0.27.0":"Đa phương tiện: trình phát, trình ghi và máy ảnh.","ladder.rung.v0.28.0":"Thư và danh bạ.","ladder.rung.v0.29.0":"Chương trình Windows: chương trình dòng lệnh.","ladder.rung.v0.30.0":"Chương trình Windows: ứng dụng có cửa sổ.","ladder.rung.v0.30.5":"Chương trình Mac: công cụ dòng lệnh.","ladder.rung.v0.30.6":"Chương trình Mac: ứng dụng có cửa sổ.","ladder.rung.v0.30.7":"Chương trình Mac: ứng dụng chỉ làm cho Apple silicon.","ladder.rung.v0.31.0":"Các ứng dụng âm nhạc Freally, với plugin VST3 và CLAP.","ladder.rung.v0.32.0":"Mọi cài đặt, mọi ngôn ngữ, và trình đọc màn hình.","ladder.rung.v0.33.0":"Cài đặt vào ổ đĩa của chính máy tính.","ladder.rung.v1.0.0-beta.N":"Bản beta: mọi tính năng được chốt, kiểm thử và ghi lại.","ladder.rung.v1.0.0-rc.N":"Bản ứng viên phát hành: mọi tính năng được kiểm thử trên phần cứng thật.","ladder.rung.v1.0.0":"Phiên bản 1.0, và lần tải xuống đầu tiên.","ladder.rung.v1.1.0 … v2.0.0":"Sau 1.0: từng phiên bản một.","ladder.note":"Phiên bản đã xong là đã được dựng, kiểm thử và gắn thẻ. Đó không phải bản tải xuống: chưa có bản nào, và sẽ không có cho đến 1.0.","honest.title":"Những điều mà hầu hết các trang web đặt ở cuối trang","honest.privacy.title":"Nó không thu thập gì","honest.privacy.body":"Không có đo lường từ xa, không gửi báo cáo lỗi, không tài khoản và không kết nối ngầm. Việc kiểm tra cập nhật, khi có, chỉ chạy khi bạn bật lên, và cho biết sẽ tải gì trước khi tải. Trang này không tải gì từ trang khác và không chạy phân tích.","honest.early.title":"Vẫn còn sớm","honest.early.body":"Hiện tại Freally OS chỉ chạy trên máy tính của chính tác giả. Nó còn làm được rất ít thứ bạn dùng hằng ngày, và con đường ở trên nói rõ khi nào từng phần sẽ đến.","honest.downloads.title":"Không có bản tải trước 1.0","honest.downloads.body":"Không có bản beta trên trang này, không có bản xem trước, không có quyền truy cập sớm. Mỗi phiên bản được dựng và kiểm thử kín cho đến 1.0.","site.tagline":"Một chiếc máy tính đứng về phía bạn.","footer.licence":"Mã nguồn mở theo Apache License 2.0. © Mike Weaver. Tên Freally, biểu tượng và giao diện không thuộc phạm vi giấy phép của mã nguồn.","footer.yours":"Tệp và tài khoản của bạn ở lại trên máy tính của bạn. Freally OS không gửi gì đi đâu trừ khi bạn yêu cầu.","featuresPage.lede":"Những gì chạy được hôm nay, và những gì Freally OS 1.0 sẽ có.","featuresPage.version":"Mọi con số trên trang này đến từ bản dựng đã tạo ra nó. Không có gì để tải xuống trước phiên bản 1.0.","featuresPage.numbers.outside":"thư viện từ bên ngoài dự án","featuresPage.numbers.ai":"mô hình AI","featuresPage.numbers.gates":"kiểm tra mỗi lần thay đổi","featuresPage.numbers.ktests":"bài kiểm tra nhân, chạy ngay trong nhân","featuresPage.numbers.specs":"kiểm tra đầu cuối trên một máy đang chạy","featuresPage.numbers.price":"giá hiện nay","featuresPage.free.title":"Hiện miễn phí","featuresPage.free.body":"Freally OS hôm nay miễn phí cho mọi người: không gói trả phí, không thuê bao và không tài khoản. Mã nguồn mở theo Apache License 2.0.","featuresPage.today.title":"Những gì chạy được hôm nay","featuresPage.today.boot.title":"Trình khởi động riêng","featuresPage.today.boot.body":"Nó đọc ảnh hệ thống, kiểm tra chữ ký và từng khối, và cho biết vì sao nó từ chối một ảnh không đạt.","featuresPage.today.kernel.title":"Freally Core, nhân hệ điều hành","featuresPage.today.kernel.body":"Bộ nhớ trong đó không gì vừa ghi được vừa chạy được, ngắt và bộ định thời, bộ lập lịch bốn lớp, và thông điệp giữa các chương trình.","featuresPage.today.conductor.title":"Chương trình đầu tiên","featuresPage.today.conductor.body":"Conductor khởi chạy như tiến trình 1, từ ảnh đã ký, trong vùng nhớ được bảo vệ của riêng nó.","featuresPage.today.faults.title":"Báo cáo lỗi","featuresPage.today.faults.body":"Chương trình bị lỗi tự dừng một mình và để lại báo cáo. Ngay cả khi nhân dừng lại cũng được báo cáo ở lần khởi động sau.","featuresPage.today.desktop.title":"Màn hình nền","featuresPage.today.desktop.body":"Rack ở dưới cùng với các phím ứng dụng và đồng hồ, trình khởi chạy trên phím Super, và cửa sổ ở chế độ sáng và tối.","featuresPage.today.terminal.title":"Terminal và Shell","featuresPage.today.terminal.body":"Dòng lệnh với shell riêng: mọi tiến trình, thời gian khởi động, nhật ký và bộ nhớ, chỉ cách một lệnh.","featuresPage.today.monitor.title":"Monitor","featuresPage.today.monitor.body":"Mọi tiến trình và công dụng của nó, quá trình khởi động từng giai đoạn, mọi sự cố và nhật ký, với Super+M.","featuresPage.today.cores.title":"Mọi lõi","featuresPage.today.cores.body":"Mọi lõi xử lý đều chạy với hàng đợi riêng, và lõi rảnh sẽ nhận việc từ lõi đang bận.","featuresPage.compare.title":"Bên cạnh các hệ thống đang được dùng","featuresPage.compare.intro":"Freally OS 1.0 bên cạnh các hệ thống máy tính mà đa số mọi người dùng, mỗi hệ thống như nhà sản xuất phát hành.","featuresPage.compare.feature":"Tính năng","featuresPage.compare.row.oneAuthor":"Mọi dòng do một tác giả viết, theo một hiến chương","featuresPage.compare.legend.yes":"có","featuresPage.compare.legend.no":"không","featuresPage.compare.row.open":"Mã nguồn mở","featuresPage.compare.legend.partly":"một phần","featuresPage.compare.note.darwin":"lõi của nó, Darwin, có","featuresPage.compare.note.chromium":"ChromiumOS có; ChromeOS thêm phần đóng","featuresPage.compare.row.noAccount":"Cài đặt không cần tài khoản trực tuyến","featuresPage.compare.note.msAccount":"khi cài đặt yêu cầu tài khoản Microsoft","featuresPage.compare.note.optional":"tài khoản là tùy chọn","featuresPage.compare.note.guest":"chỉ chế độ khách","featuresPage.compare.row.sealed":"Hệ thống được xác minh mà ứng dụng không thể thay đổi","featuresPage.compare.note.admin":"quản trị viên có thể thay đổi hệ thống","featuresPage.compare.row.windowsApps":"Chạy ứng dụng Windows","featuresPage.compare.note.layer":"ứng dụng tiêu chuẩn, qua lớp riêng","featuresPage.compare.note.addOn":"qua một tiện ích bổ sung","featuresPage.compare.row.anyPc":"Chạy trên PC bạn đã có","featuresPage.compare.note.drivers":"PC có trình điều khiển cho nó","featuresPage.compare.note.mac":"chỉ máy tính Apple","featuresPage.compare.note.flex":"PC được hỗ trợ, với ChromeOS Flex","featuresPage.compare.summaryTitle":"Tóm lại","featuresPage.compare.summary":"Chỉ Freally OS được viết hoàn toàn bởi một tác giả, theo một hiến chương. Nhờ vậy nó có thể giải thích mọi tiến trình và hứa rằng bên trong không có gì của ai khác.","featuresPage.compare.theyWinTitle":"Họ hơn ở đâu","featuresPage.compare.theyWin":"Windows, macOS, Ubuntu và ChromeOS chạy nhiều ứng dụng hơn trên nhiều phần cứng hơn rất nhiều, hôm nay và cả khi Freally OS 1.0 ra mắt. Freally OS đánh đổi độ rộng đó để nhất quán, yên tĩnh, niêm phong và được giải thích.","featuresPage.compare.asOf":"Cột của Freally OS là phiên bản 1.0, vẫn chưa ra mắt. Các hệ thống khác cũng thay đổi; bảng này tính đến tháng 11 năm 2026.","featuresPage.why.title":"Vì sao nó được làm như vậy","featuresPage.why.refused.title":"Đã ký hoặc bị từ chối","featuresPage.why.refused.body":"Mỗi bản dựng chính thức là một ảnh đã ký. Trước khi bất cứ thứ gì bên trong chạy, trình khởi động kiểm tra chữ ký và từng khối. Ảnh không đạt sẽ không bao giờ chạy, và màn hình cho biết lý do.","featuresPage.why.apps.title":"Ứng dụng không thể thay đổi hệ thống","featuresPage.why.apps.body":"Mỗi ứng dụng chạy trong hộp cát riêng, chỉ với những quyền được cấp. Bản thân hệ thống chỉ thay đổi bằng một ảnh đã ký mới.","featuresPage.why.open.title":"Mở và tái tạo được","featuresPage.why.open.body":"Mã nguồn mở, và các bản dựng có thể tái tạo: tự dựng ảnh chính thức và kiểm tra rằng nó giống hệt.","featuresPage.why.ours.title":"Mọi dòng đều là của riêng nó","featuresPage.why.ours.body":"Không có thư viện nào từ bên ngoài dự án, và một bước kiểm tra bản dựng sẽ từ chối. Ngoại lệ duy nhất là thư viện lõi của Rust và phông chữ Noto, cả hai được liệt kê trong phần thông báo.","featuresPage.coming.title":"Những gì vẫn đang đến","featuresPage.coming.intro":"Nói thẳng: Freally OS được xây từng phiên bản một, và phần lớn vẫn chưa xong. Mỗi phiên bản trên con đường đến 1.0 đều được đánh dấu trạng thái.","featuresPage.limits.title":"Những gì 1.0 không làm","featuresPage.limits.apps":"Nó sẽ không chạy mọi ứng dụng Windows hay Mac: chỉ những ứng dụng tiêu chuẩn, qua các lớp riêng.","featuresPage.limits.hardware":"Nó chạy trên máy tính x86-64 có trình điều khiển, bắt đầu với một chiếc laptop.","featuresPage.limits.servers":"Đây là hệ thống máy tính để bàn: không dành cho máy chủ hay điện thoại.","featuresPage.coming.downloads":"Không có bản tải xuống nào trước phiên bản 1.0, và cũng không có trên trang này.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.progress":"v0.4.0 đã xong · tiếp theo là v0.5.0","kit.cta.features":"Xem mọi tính năng","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.price":"Freally OS hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.goal":"Mục tiêu","kit.ladder.later":"Về sau","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Mười ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally OS, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.status.devVersion":"Đang phát triển · v0.4.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.numbers.lead":"Mỗi con số đều được đếm từ chính ứng dụng. Không có gì là ước tính, và không có gì được làm tròn lên.","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.later":"sau đó, và chưa được lên lịch","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally OS, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.search.none":"Không có gì trên trang này khớp với điều đó.","kit.zoom.close":"Đóng"};
